def protocol_handlers(cls, protocol_version=None):
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("Protocol version must be passed in a tuple")

    available_versions = {(3, 5), (3, 6)}
    available_handlers = {
        (3, 5): BoltProtocolV3_5Handler,
        (3, 6): BoltProtocolV3_6Handler,
    }

    if protocol_version is None:
        return {
            version: handler
            for version, handler in available_handlers.items()
            if version in available_versions
        }
    else:
        version = protocol_version
        handler = available_handlers.get(version)
        if handler is None:
            raise TypeError(
                "Unsupported protocol version: %s" % protocol_version)
        return {version: handler}

def protocol_handlers(protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple

    """

    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed in a tuple")

        version_tuple = (protocol_version[0], protocol_version[1])

        if version_tuple in cls.PROTOCOL_HANDLERS:
            return {version_tuple: cls.PROTOCOL_HANDLERS[version_tuple]}
        else:
            return {}
    else:
        return cls.PROTOCOL_HANDLERS

def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapped_func(tx):
            # Execute the wrapped function with the transaction object as the first argument
            result = func(tx, *args, **kwargs)

            # If the timeout is specified, use it, otherwise use the default timeout configured in the database
            timeout = timeout if timeout is not None else tx.remote.config.fetch_timeout

            # If the timeout is not None, update the transaction configuration with the new timeout
            if timeout is not None:
                tx.config(timeout=timeout)

            # If any metadata is specified, attach it to the transaction metadata
            if metadata is not None:
                tx.metadata = metadata

            return result
        return wrapped_func
    return decorator

