def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """

    def decorator(func):
        # A list of (item, frequency) pairs where item is a callable or a
        # list of arguments that can be used as a key for the cache.
        # The list is sorted by frequency, with the most frequently used
        # items at the front.
        queue = []

        # A dictionary mapping items to their respective positions in the
        # queue. This is used to quickly lookup the frequency of an item.
        # The key of the dictionary is the same as the item.
        index = {}

        # A dictionary mapping items to the values associated with the items.
        # The dictionary is used to store the cached results of the wrapped
        # function. The key of the dictionary is the same as the item.
        cache = {}

        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items()))
            if key in cache:
                return cache[key]
            if len(queue) == maxsize:
                item = queue.pop(0)
                del index[item]
                del cache[item]
            try:
                result = func(*args, **kwargs)
            except TypeError:
                # Handle the case where the function is not callable or
                # where it's called with invalid arguments.
                result = func
            if result is None:
                # If the caller doesn't want to cache None as a result,
                # just return it.
                return result
            if key not in cache:
                if typed:
                    cache[key] = result
                else:
                    cache[str(key)] = result
            if key not in index:
                index[key] = len(queue)
                queue.append(key)
            else:
                # Update the frequency of the item.
                index[key] = len(queue)
                queue.remove(key)
                queue.append(key)
            return result

        return _update_wrapper(wrapper, func)

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        class LFUCache:
            def __init__(self, maxsize):
                self.maxsize = maxsize
                self.cache = {}
                self.counter = collections.Counter()
                self.links = collections.deque()

            def get(self, key):
                if key in self.cache:
                    self._inc(key)
                    return self.cache[key]
                else:
                    return -1

            def put(self, key, value):
                self.cache[key] = value
                self.counter[key] += 1
                self._inc(key)
                return self.cache[key]

            def _inc(self, key):
                try:
                    self.links.remove(key)
                except ValueError:
                    pass
                self.links.append(key)

            def remove(self, key):
                self.cache.pop(key, None)
                self.counter.pop(key, None)
                try:
                    self.links.remove(key)
                except ValueError:
                    pass

            def clear(self):
                self.cache.clear()
                self.counter.clear()
                self.links.clear()
        cache = LFUCache(maxsize)

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = cache.get(args, kwargs)
            if key == -1:
                key = '_'.join(str(x) for x in args)
                cache.put(key, str(func(*args, **kwargs)))
            return cache[key]
        wrapper.cache = cache
        return wrapper

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        if maxsize == 0:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        else:
            freqs = {}
            cache = collections.OrderedDict()
            def wrapper(*args, **kwargs):
                key = hashkey(*args, **kwargs)
                try:
                    freqs[key] += 1
                    cache.move_to_end(key)
                    return cache[key]
                except KeyError:
                    if len(cache) == maxsize:
                        cache.popitem(last=False)
                except ValueError:
                    if freqs[key] == 1:
                        pass  # value too large, cannot be stored
                    else:
                        freqs[key] -= 1
                except TypeError:
                    if typed and not all(isinstance(arg, collections.Hashable) for arg in args):
                        raise TypeError("All arguments must be hashable")
                    else:
                        return func(*args, **kwargs)
                try:
                    return cache[key]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[key] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

