def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    result = []
    for cls in classes:
        bases = list(cls.__bases__)
        if len(bases) >= 1:
            for base in bases:
                bases = minimalBases(bases)
            result.extend(bases)
    return result

def minimalBases(classes):
