    Reduce a list of base classes to its ordered minimum equivalent

    :param classes: a list of classes
    :returns: a list of the minimal set of base classes
    """

    seen = set()
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            for b in minimalBases(cls.__bases__):
                seen.add(b)
    return list(seen)

