def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the `initial_value`
    or with `make_bins()` (depending on the initialization).
    """

    # Reset current context
    self._current_context = {}

    # Initialize bins
    if self.initial_value is not None:
        # Use the initial value for all bins
        for i in range(self.n_bins):
            self._bins[i] = self.initial_value
    else:
        # Use the provided function to initialize the bins
        self.make_bins()

