def to_csv(self, separator=",", header=None):
    raise DeprecationWarning("to_csv is not used. Iterables are converted to tables.")

    # Convert graph's points to CSV
    csv_str = ""
    if header:
        csv_str += header

    for point in self:
        point_str = ""
        for coordinate in point:
            point_str += str(coordinate)
            if coordinate != point[-1]:
                point_str += separator
        csv_str += point_str + "\n"

    return csv_str

def _get_err_indices(self, coord_name):
    """  Get error indices corresponding to a coordinate.
    """
    if coord_name not in self.err_coords:
        return []
    coord_indices = []
    for var_name, var_coord in self.err_coords[coord_name]:
        coord_indices += [(var_name, i) for i in range(len(var_coord))]
    return coord_indices

def _get_err_indices(self, coord_name):
    """  Get error indices corresponding to a coordinate.
    """
    coord = self.coords[coord_name]
    err_indices = []
    for i, err in enumerate(self.coords["err"].variable[:]):
        if np.abs(err - coord.variable[i]) >= self.tol:
            err_indices.append(i)
    return err_indices

def integral(bins, edges):
    bin_widths = edges[1:] - edges[:-1]
    return sum(bins * bin_widths)

def is_fill_request_seq(seq):
    """
    Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if isinstance(seq, FillRequestSeq):
        return True
    elif isinstance(seq, Sequence):
        return any(isinstance(item, FillRequest) for item in seq)
    return False

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if isinstance(seq, FillRequest):
        return True

    if not isinstance(seq, Sequence):
        return False

    for item in seq:
        if isinstance(item, FillRequest):
            return True

    return False

