        if hasattr(obj.__class__, 'run') and callable(obj.__class__.run):
            return True

    return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    return hasattr(obj, 'run') and callable(obj.run)

def is_fill_compute_el(obj):
    """
    Returns whether the object contains executable methods 'fill' and 'compute'.

    :param obj: The object to check
    :return: True if the object has both methods, False otherwise
    """
    if not hasattr(obj, 'fill'):
        return False
    if not hasattr(obj, 'compute'):
        return False
    if not callable(getattr(obj, 'fill')):
        return False
    if not callable(getattr(obj, 'compute')):
        return False
    return True

def is_fill_compute_el(obj):
    """Returns True if `obj` is an object that contains executable methods 'fill' and 'compute'."""
    if not isinstance(obj, (type, obj)):
        return False

    fill = False
    compute = False

    for k, v in obj.__dict__.items():
        if k == "fill" and isinstance(v, (types.FunctionType, types.MethodType)):
            fill = True
        elif k == "compute" and isinstance(v, (types.FunctionType, types.MethodType)):
            compute = True

    return fill and compute

def difference(d1, d2, level=-1):
    if level == 0:
        return {
            key: value for key, value in d1.items() if key not in d2 or value != d2[key]
        }
    else:
        res = {}
        for key, value in d1.items():
            if key not in d2 or (value != d2[key] if level == -1 or level > 1 else not difference(value, d2[key], level-1)):
                res[key] = value
        return res

def difference(d1, d2, level=-1):
    if level == 0:
        return {k: v for k, v in d1.items() if k not in d2 or v != d2[k]}
    elif level == -1:
        return {k: v for k, v in d1.items() if k not in d2 or difference(v, d2[k], level)}
    else:
        result = {}
        for k, v in d1.items():
            if k not in d2 or difference(v, d2[k], level - 1):
                result[k] = v
        return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        result = {}
        for k, v in d1.items():
            if k not in d2:
                result[k] = v
        return result
    else:
        result = {}
        for k in d1:
            if k not in d2:
                result[k] = d1[k]
            elif isinstance(d1[k], dict) and isinstance(d2[k], dict):
                result[k] = difference(d1[k], d2[k], level=level - 1)
        return result

def difference(d1, d2, level=-1):
    d1_copy = dict(d1)
    for key in d2:
        if key not in d1 or d1[key] != d2[key]:
            if level == 0 or (d1[key] != d2[key] and key not in d1):
                return {key: d2[key]}
            else:
                d1_copy.pop(key, None)
        elif isinstance(d1[key], dict) and isinstance(d2[key], dict):
            sub_diff = difference(d1[key], d2[key], level - 1)
            if sub_diff:
                d1_copy[key] = sub_diff
    return d1_copy

def difference(d1, d2, level=-1):
    d1 = copy.deepcopy(d1) if isinstance(d1, dict) else d1
    d2 = copy.deepcopy(d2) if isinstance(d2, dict) else d2
    if level == 0:
        return {k: v for k, v in d1.items() if k not in d2 or v != d2[k]}
    else:
        keys = set(d1.keys()).union(d2.keys())
        for k in keys:
            v = d1.get(k)
            v2 = d2.get(k)
            if isinstance(v, collections.Mapping) and isinstance(v2, collections.Mapping):
                v = difference(v, v2, level - 1)
            if v != v2:
                d1[k] = v
        return d1

def _validate_labels(labels):
  results = []

  for label_name, label_value in labels.items():
    match = re.match(r'[a-zA-Z0-9_]+', label_name)
    if not match:
      results.append({'label_name': f"Label key '{label_name}' does not match the regex [a-zA-Z0-9_]+"})

    # Check if the label value is a sequence
    if not isinstance(label_value, (list, tuple, set)):
      match = re.match(r'[a-zA-Z0-9_]+', label_value)
      if not match:
        results.append({'label_value': f"Label value '{label_value}' does not match the regex [a-zA-Z0-9_]+"})

  if results:
    raise ValidationError(results)

  results = []
  for label_name, label_value in labels.items():
    for value in label_value:
      match = re.match(r'[a-zA-Z0-9_]+', value)
      if not match:
        results.append({'value': f"Label value '{value}' does not match the regex [a-zA-Z0-9_]+"})

  if results:
    raise ValidationError(results)

  return results

def _validate_labels(labels):
    """
    Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    error_messages = []
    for key, value in labels.items():
        if not re.match(r"^\w+$", key):
            error_messages.append({"key": key, "value": f"Label key '{key}' does not match the regex [^A-z0-9_].`"})
        if not isinstance(value, str):
            if isinstance(value, list):
                for item in value:
                    if not isinstance(item, str):
                        error_messages.append({"key": key, "value": f"The label value for '{key}' must be a string."})
            else:
                error_messages.append({"key": key, "value": f"The label value for '{key}' must be a string."})
        if not re.match(r"^\w+$", value):
            error_messages.append({"key": key, "value": f"The label value for '{key}' does not match the regex [^A-z0-9_].`"})
    if error_messages:
        raise ValidationError(error_messages)

