def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    # Go through all observed fields, and initiliaze their value in last_applied_manifest if they are not yet present
    for i, objs in enumerate(observer_schema):
        for obs in objs:
            if obs["name"] in last_applied_manifest[i]:
                continue
            if "fields" in obs:
                last_applied_manifest[i][obs["name"]] = {}
                update_last_applied_manifest_dict_from_resp(last_applied_manifest[i][obs["name"]], obs["fields"], response[i])
            else:
                last_applied_manifest[i][obs["name"]] = response[i][obs["name"]]

    return last_applied_manifest

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in `spec.manifest` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a default observer schema.

    Returns:
        dict: The default observer schema for each Kubernetes resource present in `spec.manifest`.
    """
    # dictionary to store the default observer schema for each Kubernetes resource
    default_observer_schema = {}

    # iterate over the Kubernetes resources in `spec.manifest`
    for resource in app.spec.manifest:
        # use the meatadata name as the key for the default observer schema
        default_observer_schema[resource.name] = {
            "type": "object",
            "properties": {
                "desired": {},
                "current": {},
            },
            "required": ["desired", "current"],
        }

        # iterate over the Kubernetes resources in `spec.manifest`
        for field in resource.fields:
            # use the metadata name as the key for the default observer schema
            default_observer_schema[resource.name]["properties"][field] = {
                "type": "object",
                "properties": {
                    "spec": {
                        "type": "object",
                        "properties": {},
                        "required": [],
                    },
                    "status": {
                        "type": "object",
                        "properties": {},
                        "required": [],
                    },
                },
                "required": ["spec", "status"],
            }

            # iterate over the Kubernetes resources in `spec.manifest`
            for subfield in resource.fields[field].fields:
                # use the metadata name as the key for the default observer schema
                default_observer_schema[resource.name]["properties"][field]["properties"][subfield] = {
                    "type": "string",
                }

    return default_observer_schema

def generate_default_observer_schema(app):
    for resource in app.spec.manifest.get("resources", []):
        if resource.get("observer_schema"):
            continue

        fields = []
        # extract fields from all structs in the manifest
        for field in resource.get("fields", []):
            if field["type"] == "struct":
                for nested_field in field["fields"]:
                    fields.append(nested_field)

        # omit fields with null values
        fields = list(filter(lambda field: field["value"] is not None, fields))

        # detect and omit fields with both key and value
        fields_with_value = list(filter(lambda field: field["value"], fields))
        fields_with_key = list(filter(lambda field: field["key"], fields))
        if len(fields_with_value) == len(fields) and len(fields_with_key) == len(fields):
            fields = fields_with_value

        # omit fields with only key
        fields = list(filter(lambda field: not field["key"], fields))

        # generate default observer schema
        resource["observer_schema"] = {
            "fields": fields
        }

    return app

def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    :param sql: The SQL query.
    :type sql: str or bytes

    :param params: The set of in-style parameters.
    :type params: Mapping or Sequence

    :return: The formatted SQL query and set of converted out-style parameters.
    :rtype: tuple
    """
    if self.in_style == NamedParams:
        if not isinstance(params, Mapping):
            raise TypeError("params must be a Mapping if in_style is NamedParams")
        params = {key: value for key, value in params.items()}
    elif self.in_style == OrdinalParams:
        if not isinstance(params, Sequence) and not isinstance(params, tuple):
            raise TypeError("params must be a Sequence or tuple if in_style is OrdinalParams")
        params = list(params)
    else:
        raise ValueError(f"Unsupported in_style: {self.in_style}")

    formatted_sql = sql.format(**params)
    return formatted_sql, params

def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    :param sql: The SQL query.
    :type sql: str or bytes
    :param params: The set of in-style parameters.
    :type params: Union[Dict[Union[str, int], Any], Sequence[Any]]
    :return: The formatted SQL query and the set of converted out-style parameters.
    :rtype: Tuple[str, Union[Dict[Union[str, int], Any], Sequence[Any]]]
    """
    if self.in_style == ParameterStyle.NAMED:
        if not isinstance(params, dict):
            raise ValueError("Invalid parameter type")
        formatted_params = {}
        for param, value in params.items():
            formatted_params[f":{param}"] = value
        return sql.format_map(formatted_params), formatted_params
    elif self.in_style == ParameterStyle.ORDINAL:
        if not isinstance(params, list):
            raise ValueError("Invalid parameter type")
        return sql % tuple(params), params

def formatmany(self, sql, many_params):
    assert isinstance(many_params, (list, tuple, set))

    formatted_params = []
    for params in many_params:
        formatted_params.append(self.format(sql, params))

    return sql, formatted_params

