def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Check if path is valid
    if not os.path.exists(path):
        raise errors.PathExistsError(f'Path {path} does not exist')

    # Check if path is a directory
    if not os.path.isdir(path):
        raise errors.NotADirectoryError(f'Path {path} is not a directory')

    # Check if path contains OCFL manifest
    if not os.path.exists(os.path.join(path, 'VERSION')):
        raise errors.NotAFileError(f'Path {path} does not contain a VERSION file')

    # Check if path contains OCFL root directory
    if not os.path.exists(os.path.join(path, 'ocfl-1.0')):
        raise errors.NotAFileError(f'Path {path} does not contain an ocfl-1.0 file')

    # Check if path contains OCFL digest root directory
    if not os.path.exists(os.path.join(path, 'ocfl-1.0', 'digests')):
        raise errors.NotAFileError(f'Path {path} does not contain a digests directory')

    # Check if path contains OCFL root json file
    if not os.path.exists(os.path.join(path, 'ocfl-1.0', 'root.json')):
        raise errors.NotAFileError(f'Path {path} does not contain a root.json file')

    # Check if path contains OCFL inventory json file
    if not os.path.exists(os.path.join(path, 'ocfl-1.0', 'inventory.json')):
        raise errors.NotAFileError(f'Path {path} does not contain an inventory.json file')

    return True

