def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """

    if extract_spec_version:
        # Determine the specification version based on the type value
        if 'type' in inventory:
            spec_version = inventory['type']
            if spec_version in self.spec_version.keys():
                spec_name = self.spec_version.get(spec_version)
                if spec_name is not None:
                    self.spec = importlib.import_module(spec_name)
                    self.version = spec_version
                    self.spec_name = spec_name
            else:
                raise ValueError('Unsupported specification version {}'.format(spec_version))
        else:
            raise ValueError('Required "type" field is missing')
    else:
        # Use the default specification version specified in self.spec_version
        self.spec = importlib.import_module(self.spec_name)
        self.version = self.spec_version.get(self.version)

    # Perform validation
    for key, value in inventory.items():
        if key in self.spec.keys():
            self.spec.keys[key].validate(value)
        else:
            raise KeyError('Unsupported key {}'.format(key))

    return inventory

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        if not isinstance(inventory, dict):
            raise ValueError("Inventory must be a dictionary")

        # extract the specification version from the type field
        if extract_spec_version:
            type_value = inventory.get("type")
            if type_value is not None:
                # validate the type value based on the specification version
                if not self._validate_type(type_value):
                    raise ValueError("Invalid type value")

                # determine the specification version based on the type value
                self.spec_version = type_value.split(":")[1]

        # validate the inventory against the defined schema
        for field, value in inventory.items():
            if not self._validate_field(field, value):
                raise ValueError("Invalid value for field %s" % field)

        return inventory

