def validate_as_prior_version(self, prior):
        """
        Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if self == prior or self.steepest_descent_vector != prior.steepest_descent_vector:
            raise ValueError('The input prior is not a valid prior version of this inventory object')

        if self.objective_expressions != prior.objective_expressions:
            raise ValueError('The input prior has a different set of objective expressions than this inventory object')

        if self.bounds != prior.bounds:
            raise ValueError('The input prior has different bounds than this inventory object')

        for expr in self.objective_expressions:
            p_val = prior.expression_value(expr)
            c_val = self.expression_value(expr)
            if p_val != c_val:
                raise ValueError(f'The input prior has different value for expression {expr!r} than this inventory object')

        for bound in self.bounds:
            p_val = prior.expression_value(bound[0])
            c_val = self.expression_value(bound[0])
            if p_val != c_val:
                raise ValueError(f'The input prior has different value for bound {bound!r} than this inventory object')

def get_logical_path_map(inventory, version):
    """
    Returns a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """

    content_files = {}

    for entry in inventory.get_entries(version):
        if not entry.has_logical_path:
            continue

        logical_path = entry.logical_path
        if logical_path in content_files:
            content_files[logical_path].add(entry.path)
        else:
            content_files[logical_path] = {entry.path}

    return content_files

def get_logical_path_map(inventory, version):
    '''
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    '''

    logical_path_map = {}

    for path, files in inventory.items():
        for file in files:
            logical_path = file['logical_path']
            content_files = file['content_files']
            if version in content_files:
                logical_path_map[logical_path] = content_files

    return logical_path_map

def get_logical_path_map(inventory, version):
    """
