    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for item in inventory:
        for logical_path in item.logical_paths:
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()
            logical_path_map[logical_path].add(item.abs_content_file)
    return logical_path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """

    logical_path_map = {}
    for package in inventory.get_package_map().values():
        for logical_path in package.get_logical_paths(version):
            content_files = package.get_content_files_by_logical_path(
                logical_path, version
            )
            if content_files:
                logical_path_map[logical_path] = set(content_files)

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary")
    if not isinstance(manifest_files, list):
        raise ValueError("Manifest files must be a list")

    for file in manifest_files:
        if file not in fixity:
            raise ValueError(f"{file} is not in the fixity block")
        hash_type, expected_hash = fixity[file].split("-", 1)
        if not hash_type or not expected_hash:
            raise ValueError(f"Invalid hash type and expected hash for {file}")

    for file in fixity.keys():
        if file not in manifest_files:
            raise ValueError(f"{file} is not in the manifest")
        if not fixity[file].endswith("-" + expected_hash):
            raise ValueError(f"File {file} has an invalid hash")

    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files listed in the manifest are referenced.
    """
    if not isinstance(fixity, list):
        raise ValueError("Fixity block is not a list")

    for file in fixity:
        if not isinstance(file, dict):
            raise ValueError("Fixity file is not a dictionary")
        if not file.get("checksum_type") or not file.get("checksum_value") or not file.get("source_file"):
            raise ValueError("Invalid fixity file.")

    for file in manifest_files:
        if file not in [f["source_file"] for f in fixity]:
            raise ValueError("Manifest file {} is not in fixity block.".format(file))

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    # check if fixity is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary")

    # check if fixity has the correct keys
    required_keys = ["files", "algorithms"]
    for key in required_keys:
        if key not in fixity:
            raise ValueError(f"Fixity must contain key '{key}'")

    # check if files is a list
    files = fixity["files"]
    if not isinstance(files, list):
        raise ValueError("Fixity 'files' must be a list")

    # check if files are all strings
    for file in files:
        if not isinstance(file, str):
            raise ValueError("Fixity 'files' must contain only strings")

    # check if algorithms is a list
    algorithms = fixity["algorithms"]
    if not isinstance(algorithms, list):
        raise ValueError("Fixity 'algorithms' must be a list")

    # check if algorithms are all strings
    for algorithm in algorithms:
        if not isinstance(algorithm, str):
            raise ValueError("Fixity 'algorithms' must contain only strings")

    # check if files are all in the manifest
    for file in files:
        if file not in manifest_files:
            raise ValueError(f"File '{file}' is not in the manifest")

    # check if algorithms are all available in the inventory
    for algorithm in algorithms:
        if algorithm not in self.inventory.get_algorithms():
            raise ValueError(f"Algorithm '{algorithm}' is not available in the inventory")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if 'fixity' not in fixity:
        raise ValueError("'fixity' field not found in the given inventory.")
    if not isinstance(fixity['fixity'], list):
        raise ValueError("'fixity' field must be a list of dictionaries.")
    for i, f in enumerate(fixity['fixity']):
        if not isinstance(f, dict):
            raise ValueError(f"Element at position {i} in 'fixity' field is not a dictionary.")
        if not f.get('file'):
            raise ValueError(f"Element at position {i} in 'fixity' field missing 'file' field.")
        if not f.get('hash'):
            raise ValueError(f"Element at position {i} in 'fixity' field missing 'hash' field.")
        if f['file'] not in manifest_files:
            raise ValueError(f"File {f['file']} is not listed in the manifest.")

