def _explore_folder(folder):
    # Initialize an empty dictionary to store the data
    package_data = {}

    # Iterate over the files in the folder
    for filename in os.listdir(folder):
        # Extract the XML basename from the filename
        basename = extract_xml_basename(filename)

        # If there is no data for this basename yet, create a new entry
        if basename not in package_data:
            package_data[basename] = {
                # store the filename as a list for now
                'filenames': [filename],
                # set an empty dict to store the data
                'data': {}
            }
        else:
            # If there is already data for this basename, add the filename to the list
            package_data[basename]['filenames'].append(filename)

        # Try to load the data from the file
        try:
            with open(os.path.join(folder, filename), 'r') as f:
                data = xml_load(f)

            # If the data is valid, add it to the data dictionary
            if data:
                package_data[basename]['data'].update(data)
        except xml_utils_Error as e:
            # If the data is not valid, print a warning message
            print(f'Warning: failed to load data from {filename}: {e}')

    return package_data

def _explore_folder(folder):
