def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.

    @ indent: #int level of indentation
    @ debug: #bool whether to print debug information

    -> #str pretty formatted representation of self
    """
    if isinstance(self, (list, tuple)):
        s = "(\n"
        with indent(indent + 2):
            for elem in self:
                s += pretty(elem, indent + 2, debug) + ",\n"
            return s.rstrip(",\n") + "\n" + indent(indent) + ")"
    elif isinstance(self, dict):
        s = "{\n"
        with indent(indent + 2):
            for key, value in self.items():
                s += pretty(key, indent + 2, debug) + ": " + pretty(value, indent + 2, debug) + ",\n"
            return s.rstrip(",\n") + "\n" + indent(indent) + "}"
    else:
        return str(self)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if "&" in arg and "|" in arg:
            lhs, rhs = arg.split("&")
            if "|" in lhs:
                new_args.append(lhs + " & " + rhs)
            else:
                new_args.append(lhs + " & " + rhs)
        elif "|" in arg and "~" in arg:
            lhs, rhs = arg.split("|")
            if "&" in rhs:
                new_args.append(lhs + " & " + rhs)
            else:
                new_args.append(lhs + " | " + rhs)
        else:
            new_args.append(arg)
    return new_args

