def _fromutc(self, dt):
    if not dt.tzinfo:
        return dt.replace(tzinfo=localtz())
    dttz = datetime_tz(dt)
    if dttz.fold:
        dttz = dttz.normalize()
    return dttz.astimezone(localtz())

