def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    for object_path in self.get_object_paths():
        num_objects += 1
        try:
            digest = self.get_object(object_path).get_digest()
        except AttributeError:
            if show_warnings:
                print(f'WARNING: {object_path}: missing digest')
            continue
        if check_digests and (digest != self.get_object(object_path).get_digest()):
            if show_warnings:
                print(f'WARNING: {object_path}: corrupt digest')
            continue
        if validate_objects and not self.get_object(object_path).is_valid():
            if show_warnings:
                print(f'WARNING: {object_path}: invalid content')
            continue
        good_objects += 1
    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if len(version) == 1:
        return "0" + version + "." + "0"
    elif len(version) == 2:
        return version + "." + "0"
    else:
        release, major, minor = parse_version(version)
        minor = str(int(minor) + 1)
        return release + "." + major + "." + minor

def validate_version_inventories(self, version_dirs):
