def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        # Check if the path corresponds to an OCFL Storage Root
        with open(os.path.join(path, "0=*"), "r") as f:
            if "OCFL Object" in f.read():
                return "root"
    except FileNotFoundError:
        pass

    try:
        # Check if the path corresponds to an OCFL Object
        with open(os.path.join(path, "inventory.xml"), "r") as f:
            if "OCFL Object" in f.read():
                return "object"
    except FileNotFoundError:
        pass

    try:
        # Check if the path corresponds to a file
        with open(path, "r") as f:
            if f.read().startswith("OCFL File"):
                return "file"
        return "file"
    except FileNotFoundError:
        return "unknown"

    return "unknown"

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not os.path.isdir(path):
        return "file"

    for root, dirs, files in os.walk(path):
        for file in files:
            if file.startswith("0=") and file.endswith(".tml"):
                if "http://sche.mannlib.indiana.edu/ns/ocfl/1.0/namaste" in open(os.path.join(root, file)).read():
                    return "root"
                return "object"

    return "file"

