def deep_merge_nodes(nodes):
    result = {}
    for key, value in nodes:
        current_value = result.get(key)
        if current_value is None:
            if isinstance(value, ruamel.yaml.nodes.MappingNode):
                result[key] = value
            else:
                result[key] = current_value
        elif isinstance(value, ruamel.yaml.nodes.MappingNode):
            if not isinstance(current_value, ruamel.yaml.nodes.MappingNode):
                result[key] = value
            else:
                for subkey, subvalue in value.value:
                    current_subkey = current_value.value(subkey)
                    if current_subkey is None:
                        result.setdefault(subkey, subvalue)
                    elif isinstance(current_subkey, ruamel.yaml.nodes.MappingNode):
                        result[subkey] = deep_merge_nodes([
                            (current_subkey.key, current_subkey.value),
                            (subkey, subvalue),
                        ])
                    else:
                        result[subkey] = subvalue
    return result

def deep_merge_nodes(nodes):
    result = []

    for key, value in nodes:
        if value.id <= 0:
            # Handling ScalarNode
            matching_key = key
            new_value = value
        else:
            # Handling MappingNode
            matching_key = next(
                (
                    match_key
                    for match_key, match_val in result
                    if match_key.value == key.value
                ),
                key,
            )
            new_value = merge_value(matching_key.value, value)

        if not any(k.value == key.value for k, v in result):
            result.append((matching_key, new_value))

    return result

def deep_merge_nodes(nodes):
    """Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """
    # Convert the node tuples into dictionaries for convenience
    node_dict = {}
    for node in nodes:
        node_dict[node[0].value] = node[1]

    for key, node in node_dict.items():
        if isinstance(node, ruamel.yaml.nodes.MappingNode):
            # For MappingNodes, deep merge the respective values
            nested_node_list = []
            for scalar_key, value in node.value:
                if scalar_key.value == key:
                    nested_node_list.append((scalar_key, value))
            for nested_key, nested_value in deep_merge_nodes(nested_node_list):
                node.value.append((nested_key, nested_value))

    # Peel the scalar mapping keys off and return the flattened list of node tuples
    return [(key, value) for key, node in node_dict.items() for value in node.value]

