def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    namespace = {}
    lefover_args = []
    for arg in unparsed_arguments:
        for subparser_name, subparser in subparsers.items():
            sub_args, subparser_args = subparser.parse_known_args([arg])
            if sub_args is not None and sub_args.repository is not None:
                # The subparser consumed the argument
                if sub_args.repository not in namespace:
                    namespace[sub_args.repository] = {}
                namespace[sub_args.repository][subparser_name] = sub_args
                break
        else:
            # The subparser did not consume the argument
            lefover_args.append(arg)
    return namespace, lefover_args

def parse_subparser_arguments(unparsed_arguments, subparsers):
    subparser_arguments = {}
    remaining_arguments = []
    for argument in unparsed_arguments:
        for subparser, parser in subparsers.items():
            if argument in parser.args:
                if subparser not in subparser_arguments:
                    subparser_arguments[subparser] = parser.parse_args(
                        argument.split())
                    break
                else:
                    raise ValueError("parser already contains an argument with the same name")
        else:
            remaining_arguments.append(argument)
    return subparser_arguments, remaining_arguments

def size_to_bytes(size: str) -> int:
    names = ('B', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB')
    size = size.upper()
    split_size = size.split()

    if split_size[1] in names:
        return int(split_size[0]) * math.pow(1024, names.index(split_size[1]))
    else:
        raise ValueError(f"Cannot convert {size} to bytes as it is not a standard file size unit.")

