def replace_value(flow_params, register_number, register_value):
    """Replace value from registration number to the given value.

    The 'register_value' key in the dictionary will be replaced by the register number given.

    :param flow_params: Dictionary containing register assignments.
    :type flow_params: dict
    :param register_number: The number of the register to store the value.
    :type register_number: int
    :param register_value: The value to store in the register.
    :type register_value: int
    :return: Dictionary with the replaced register value.
    :rtype: dict
    """

    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")

    if not isinstance(register_number, int):
        raise TypeError("register_number must be an integer")

    if not isinstance(register_value, int):
        raise TypeError("register_value must be an integer")

    if register_number < 0:
        raise ValueError("register_number must be non-negative")

    if register_value < 0:
        raise ValueError("register_value must be non-negative")

    return {**flow_params, register_value: register_number}

