def split(s, platform='this'):
    if platform == 'this':
        platform = sys.platform
    if platform.lower().startswith('win'):
        # Windows/CMD
        from _winreg import QueryValueEx
        if platform == 'win32':
            # not available for 64bit
            native = True
            separator = QueryValueEx(
                _winreg.OpenKey(
                    _winreg.HKEY_LOCAL_MACHINE,
                    r'SYSTEM\CurrentControlSet\Control\Nls\CodePage'),
                'OEMCP')[0]
        elif subprocess.check_output(["wmic", "os", "get", "osarchitecture"]).decode(
                "utf-8").startswith('64'):
            # wmic is limited to 16bit string length
            native = True
            separator = 1252
        else:
            native = False
            separator = 1254
        if native:
            regex = '<|>|\||&|"|"|' + chr(separator)
        else:
            regex = '<|>|\||&|"|"|\\\|' + chr(separator)
    else:
        # POSIX
        regex = '<|>|\||&|"|"'
    return re.split(regex, s, maxsplit=32)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Detect platform
    if platform == 'this':
        platform = 'POSIX' if sys.platform.startswith('linux') or sys.platform == 'darwin' else 'Windows/CMD'

    if platform == 'POSIX':
        # Split using shell-like syntax
        return shlex.split(s)
    elif platform == 'Windows/CMD':
        # Split using Windows/CMD syntax
        pattern = r'[&|<>()@^]|".*?("?)'
        parts = re.split(pattern, s)
        return [part for part in parts if part]
    else:
        raise ValueError('Unsupported platform: ' + platform)

def split(s, platform='this'):
