def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''

    if frequency is None or frequency == "always":
        return None

    m = re.match(r'^(?P<n>\d+)\s*(?P<unit>\w+)$', frequency)
    if not m:
        raise ValueError("Invalid frequency format: '%s'" % frequency)

    n = int(m.group('n'))
    unit = m.group('unit')
    if unit == "years":
        return datetime.timedelta(n * 365.25 * 24 * 60 * 60)
    elif unit == "quarters":
        return datetime.timedelta(n * 91.31 * 24 * 60 * 60)
    elif unit == "months":
        return datetime.timedelta(n * 30.4375 * 24 * 60 * 60)
    elif unit == "weeks":
        return datetime.timedelta(n * 604800)
    elif unit == "days":
        return datetime.timedelta(n * 86400)
    elif unit == "hours":
        return datetime.timedelta(n * 3600)
    elif unit == "minutes":
        return datetime.timedelta(n * 60)
    elif unit == "seconds":
        return datetime.timedelta(n * 1)
    else:
        raise ValueError("Invalid frequency unit: '%s'" % unit)

