    """
    Call the given command(s).

    :param commands: The command(s) to run.
    :type commands: list

    :param args: The arguments to supply to the command(s).
    :type args: list

    :param cwd: The working directory in which to run the command(s).
    :type cwd: str

    :param verbose: Whether to print the output of the command(s).
    :type verbose: bool

    :param hide_stderr: Whether to hide the error output of the command(s).
    :type hide_stderr: bool

    :param env: The environment variables to set before running the command(s).
    :type env: dict

    :return: The return code of the command(s).
    :rtype: int
    """

    if not isinstance(commands, list):
        commands = [commands]

    if env is None:
        env = os.environ

    if not hide_stderr and verbose:
        command_string = "Running the following command(s):"
        for command in commands:
            command_string += " " + str(command)
        print(command_string)

    if len(commands) == 1:
        command = commands[0]

        if not isinstance(args, list):
            args = [args]

        if verbose:
            print(f"Arguments: {args}")

        try:
            p = subprocess.run(command, args, cwd=cwd, check=True, env=env)
            if verbose:
                print(f"PID: {p.pid}")
                print(f"Exit code: {p.returncode}")
            return p.returncode
        except subprocess.CalledProcessError:
            print("Output:")
            return 1
    else:
        processes = []

        for command in commands:
            if verbose:
                print(f"Running command: {command}")

            p = subprocess.Popen(command, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=cwd, env=env)
            processes.append(p)

        for p in processes:
            out, err = p.communicate()

            if verbose:
                print(f"PID: {p.pid}")
                if out:
                    print(f"Output: {out.decode()}")
                if err:
                    print(f"Error: {err.decode()}")

                print(f"Exit code: {p.returncode}")

        return 0

