def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to
    corresponding parsed configuration, and sequence of logging.LogRecord
    instances containing any parse errors.
    """
    configs = {}
    parse_errors = []
    for config_filename in config_filenames:
        try:
            with open(config_filename) as fd:
                config = toml.loads(fd.read())
            configs[config_filename] = config
        except toml.TomlDecodeError as e:
            parse_errors.append(e)
    if overrides:
        for key, value in overrides.items():
            if key not in configs['config_filename']:
                configs['config_filename'][key] = value
    for config_filename in configs:
        for error in parse_errors:
            logging.error(f"Error parsing {config_filename}: {error}")
    return configs, parse_errors

