def _verify(iface, candidate, tentative=False, vtype=None):
    # Make sure the candidate claims that it provides the interface using iface.providedBy
    if not tentative:
        if not iface.providedBy(candidate):
            raise zope.interface.Invalid(
                "Object does not implement {}".format(iface))

    # Make sure the candidate defines all the necessary methods
    for method in iface.names():
        # If this method is __dummy__, ignore it
        if method != "__dummy__":
            # Get the method on the candidate
            cmethod = getattr(candidate, method, None)
            # Check that the method exists
            if cmethod is None:
                raise zope.interface.Invalid(
                    "Object does not implement method {}".format(method))

    # Make sure the candidate defines all the necessary attributes
    for attr in iface.getAttributeNames():
        # If this attribute is __dummy__, ignore it
        if attr != "__dummy__":
            # Check that the attribute exists
            cattr = getattr(candidate, attr, None)
            if cattr is None:
                raise zope.interface.Invalid(
                    "Object does not implement attribute {}".format(attr))

    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """

    if tentative or iface.providedBy(candidate):
        # Check that the candidate defines all the necessary methods
        for method_name, method in iface.namesAndDescriptions().items():
            if not hasattr(candidate, method_name):
                if not tentative:
                    raise Invalid("Missing '{}' method".format(method_name))

        # Check that the methods have the correct signature (to the
        # extent possible)
        for method_name in iface.names():
            method = getattr(candidate, method_name)
            for idx, arg in enumerate(method.im_func.func_code.co_varnames):
                if idx >= len(method.im_func.func_defaults):
                    break
                if method.im_func.func_defaults[idx] is not Ellipsis:
                    default_value = method.im_func.func_defaults[idx]
                    if default_value is not None and method.im_func.func_code.co_varnames[idx] in method.im_func.func_code.co_varkeys:
                        parameter = method.im_func.func_code.co_varkeys[method.im_func.func_code.co_varnames[idx]]
                        parameter_type = parameter[0]
                        if parameter_type is not None and default_value is not None:
                            try:
                                parameter_type.type_check(default_value)
                            except TypeError:
                                raise Invalid("Invalid default value '{}' for argument '{}' in method '{}'".format(default_value, arg, method_name))

        # Check that the candidate defines all the necessary attributes
        for attr in iface.names(interface.IAttribute):
            if not hasattr(candidate, attr):
                if not tentative:
                    raise Invalid("Missing '{}' attribute".format(attr))

    else:
        raise Invalid("'{}' does not provide '{}'".format(candidate, iface))

