def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # First, check that the candidate implements all the required methods
    for method in iface.methods:
        if method not in candidate.methods:
            return False

    # Next, check that the candidate's implementations of the
    # methods in the interface are equivalent or more permissive
    for method in iface.methods:
        iface_method = iface.methods[method]
        candidate_method = candidate.methods[method]
        if not candidate_method.isMoreSpecificThan(iface_method):
            return False

    # Finally, if this is a tentative verification, return True
    # otherwise check that the candidate's __class__ variable
    # is a subclass of the interface
    if tentative:
        return True
    else:
        return issubclass(candidate.__class__, iface)

