def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request

    :param request: The request to identify
    :return: True if the request is a Matrix request, False otherwise
    """

    if not request:
        raise ValueError('request must be provided')

    if not isinstance(request, RequestType):
        return False

    if not request.body:
        return False

    try:
        data = json.loads(request.body)
    except ValueError:
        return False

    if not isinstance(data, dict):
        return False

    if 'type' not in data or 'action' not in data:
        return False

    if data['type'] != 'MESSAGE_RECEIPT':
        return False

    if data['action'] != 'marked':
        return False

    if 'matrix' not in data or 'content' not in data['matrix']:
        return False

    content = data['matrix']['content']

    if not isinstance(content, dict):
        return False

    if 'kind' not in content or 'message' not in content:
        return False

    if content['kind'] != 'uia':
        return False

    if content['message'] != 'message':
        return False

    if 'rel_ids' not in content:
        return False

    rel_ids = content['rel_ids']

    if not isinstance(rel_ids, list):
        return False

    if len(rel_ids) != 1:
        return False

    rel_id = rel_ids[0]

    if not isinstance(rel_id, str):
        return False

    # Assuming the rel_id is in the format of ${event_id}:${transaction_id}
    parts = rel_id.split(':')

    if len(parts) != 2:
        return False

    event_id = parts[0]
    transaction_id = parts[1]

    if not isinstance(event_id, str):
        return False

    if not isinstance(transaction_id, str):
        return False

    return True

