def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    new_text = ''
    for line in text.split('\n'):
        if line.startswith("#"):
            tag_word = line.lstrip("# ").strip()
            if replacer is not None:
                new_line = replacer(tag_word)
                new_text += f"#{new_line}"
            else:
                new_text += line
            tags.add(tag_word)
        else:
            new_text += line + '\n'
    return tags, new_text

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    replaced_text = ''
    in_code_block = False
    for line in text.split('\n'):
        if not in_code_block:
            for match in re.finditer(r'<[^>]+>', line):
                tag = match.group()[1:-1]
                tags.add(tag)
                replaced_text += f'{replacer(tag)}' if replacrer else f'{tag}'
            if '<' in line or '>' in line:
                in_code_block = True
        else:
            in_code_block = False
    return tags, replaced_text

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    changed_text = ''
    in_code = False

    for line in text.splitlines():
        if not in_code:
            for match in re.finditer(r'\\b([a-zA-Z0-9_]+) \#', line):
                tag = match.group(1)
                tags.add(tag)
                changed_text += line[:match.start()] + tag + '\n'

        if line.strip().startswith('```'):
            in_code = not in_code

    if replacer is not None:
        for tag in tags:
            changed_text = changed_text.replace(tag, str(replacer(tag)))

    return tags, changed_text

