    def to_url(m):
        # Detect if the link is a http(s) URL or a file path.
        if m.group(1):
            return m.group(0)  # It's an http(s) URL.

        path = m.group(0)
        if path.startswith('http://') or path.startswith('https://'):
            # It's an URL, return it as is.
            return m.group(0)

        # It's a file path, convert it to a URL.
        return '/browse/{}'.format(m.group(0))

    def add_target_blank(url, text):
        # If the link is not an URL, don't add the target attribute.
        if url is not None:
            # Add the target="_blank" attribute to the link.
            return '<a target="_blank" href="{}">{}</a>'.format(url, text)

    return _PATH_RE.sub(lambda m: add_target_blank(to_url(m), m.group(0)), text)

