def verify_relayable_signature(public_key, doc, signature):
    # Check the signature confirming that it was properly signed by the key
    if public_key.verify(
            doc.encode('utf-8'),
            signature.encode('utf-8'),
            algorithms.RSA_SHA256):
        return True
    else:
        return False

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    return public_key.VerifyString(doc, signature)

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Check that the signature is valid
    if not public_key.verify(signature, doc):
        raise ValueError("Invalid signature")

    # Check the signature timestamp (if present)
    signature_timestamp = doc.find(".//s:Signature/ds:SignatureValue/Timestamp", namespaces={"s": "http://www.w3.org/2000/09/xmldsig#", "ds": "http://www.w3.org/2000/09/xmldsig#"})
    if signature_timestamp is not None and signature_timestamp.text:
        signature_timestamp = datetime.strptime(signature_timestamp.text, "%Y-%m-%dT%H:%M:%S%z")
        if signature_timestamp < datetime.now() - timedelta(seconds=10):
            raise ValueError("Signature timestamp too old")

    # Check the signature type (if present)
    signature_type = doc.find(".//s:Signature/ds:SignatureValue/Type", namespaces={"s": "http://www.w3.org/2000/09/xmldsig#", "ds": "http://www.w3.org/2000/09/xmldsig#"})
    if signature_type is not None and signature_type.text:
        if signature_type.text != "http://www.w3.org/2000/09/xmldsig#rsa-sha256":
            raise ValueError("Unsupported signature type")

