def parse_diaspora_webfinger(document: str) -> Dict:
    """ Parse Diaspora webfinger which is either in JSON format (new) or XRD (old). """

    # JSON format (new)
    try:
        data = json.loads(document)
        return {
            "subject": data.get("subject"),
            "aliases": data.get("aliases"),
            "properties": data.get("properties"),
            "links": data.get("links"),
        }
    except (ValueError, json.JSONDecodeError):
        pass

    # XRD format (old)
    try:
        data = xmltodict.parse(document)
    except xmltodict.ParsingError:
        print("Failed to parse Diaspora webfinger XRD format")
        return {}
    links = []
    for link in data.get("XRD", {}).get("Link", []):
        rel = link.get("rel")
        if rel != "lrdd":
            continue
        template = link.get("template")
        if template is None:
            continue
        links.append(template)
    return {"links": links}

