def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger, which can be in JSON format (new) or XRD (old).

    :param document: The Diaspora webfinger document as a string.
    :returns: A dictionary containing the parsed webfinger data.
    """
    try:
        return json.loads(document)
    except json.JSONDecodeError:
        pass

    xrd = lxml.etree.fromstring(document)
    links = xrd.findall(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link")
    webfinger = {
        "subject": xrd.findtext(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject"),
        "aliases": [
            link.attrib["{http://docs.oasis-open.org/ns/xri/xrd-1.0}href"]
            for link in links
            if link.attrib["{http://docs.oasis-open.org/ns/xri/xrd-1.0}rel"] == "lrdd"
        ],
        "hcard_url": [
            link.attrib["{http://docs.oasis-open.org/ns/xri/xrd-1.0}href"]
            for link in links
            if link.attrib["{http://docs.oasis-open.org/ns/xri/xrd-1.0}rel"] == "hcard"
        ],
    }
    return webfinger

