def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of file names that match the provided specifications.

    :param settings_dirs: list of directories to search for settings files
    :param spec_option: the specifications to use when searching for settings files
    :return: a list of file names that match the provided specifications
    """

    file_names = []

    for directory in settings_dirs:
        for root, subdirs, files in os.walk(directory):
            for file in files:
                if spec_option.match(file) is not None:
                    file_names.append(os.path.join(root, file))

    return file_names

