def validate_from_content(spec_content):
    """
    validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if not spec_content:
        raise IRValidatorException("Spec content is missing")

    try:
        loaded_spec = yaml.load(spec_content, Loader=yaml.FullLoader)
    except yaml.YAMLError as exc:
        raise IRValidatorException(f"Failed to load spec content: {exc}")

    # Check if all mandatory fields are present
    for field in cls.mandatory_fields:
        if field not in loaded_spec:
            raise IRValidatorException(f"Mandatory field {field} is missing")

    # Check if all additional fields have their specified types
    for field, value in loaded_spec.items():
        if field in cls.allowed_types:
            if not isinstance(value, cls.allowed_types[field]):
                raise IRValidatorException(f"Invalid type for field {field}: {type(value).__name__}")

    # Check if all fields have valid values
    for field, value in loaded_spec.items():
        if field in cls.field_validators:
            validator = cls.field_validators[field]
            if not validator(value):
                raise IRValidatorException(f"Invalid value for field {field}: {value}")

    return loaded_spec

def validate_from_content(content=None):
    """Validates that the given spec content has all required fields.

    :param content: Content of the spec file
    :return: Dictionary with data loaded from the spec file
    """

    # Validate whether the content is empty or not
    if content is None or content == "":
        raise IRValidatorException("Spec content is empty or not provided.")

    # Load the spec content as YAML
    try:
        data = yaml.load(content, Loader=yaml.SafeLoader)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error loading spec content: {e}")

    # Validate whether the data is a dictionary or not
    if not isinstance(data, dict):
        raise IRValidatorException(f"Spec content is not in a valid YAML format.")

    # Validate whether the content has the required fields
    required_fields = ("title", "version", "representations")
    for field in required_fields:
        if field not in data:
            raise IRValidatorException(f"Required field '{field}' is missing in the spec content.")

    return data

def validate_from_content(spec_content):
    """Validates that spec content has all required fields.
    :param spec_content: Content of spec file.
    :raises IRValidatorException: When mandatory data is missing in spec file.
    :return: Dictionary with data loaded from a spec (YAML) file.
    """

    if spec_content is None:
        raise IRValidatorException("Spec content is None.")

    try:
        loaded_spec = yaml.safe_load(spec_content)
    except yaml.scanner.ScannerError:
        raise IRValidatorException("Spec content is not a valid YAML.")

    required_fields = ["name", "version", "user", "project", "cmd"]

    missing_fields = []
    for field in required_fields:
        if field not in loaded_spec:
            missing_fields.append(field)

    if missing_fields:
        raise IRValidatorException(
            f"The following mandatory fields are missing: {', '.join(missing_fields)}."
        )

    return loaded_spec

def validate_from_file(yaml_file=None):
    """
    Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise ValueError("yaml_file argument must be supplied")

    with open(yaml_file, 'r') as f:
        data = yaml.safe_load(f)

    if 'type' in data and data['type'] == 'IRValidatorSpec':
        return cls.validate_ir_validator_spec(data)
    else:
        return cls.validate_ir_validator(data)

