    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    for group, items in parser_dict.items():
        if not isinstance(items, dict):
            # Non-dictionary includes are not allowed
            raise ValueError("Invalid include syntax for group %s" % group)
        for item, item_info in items.items():
            if not isinstance(item_info, dict):
                # Non-dictionary includes are not allowed
                raise ValueError("Invalid include syntax for item %s" % item)
            if "include" not in item_info:
                # No include specified
                continue
            include_file = item_info["include"]
            if not os.path.isfile(include_file):
                # Included file does not exist
                raise FileNotFoundError("Could not find included file %s for item %s" % (include_file, item))
            include_dict = self._parse_file(include_file)
            for include_item_name, include_item_info in include_dict.items():
                # Add include item to the group
                parser_dict[group].setdefault(include_item_name, {})
                parser_dict[group][include_item_name].update(include_item_info)

def include_groups(self, parser_dict):
    included_groups = {}
    for group_name, group_vals in parser_dict.items():
        if group_name.startswith("@"):
            group_name = group_name[1:]
            if group_name not in self.include_groups:
                raise ValueError("Unknown include group: %s" % group_name)
            included_groups[group_name] = parser_dict[group_name]
        else:
            included_groups[group_name] = group_vals
    return included_groups

def include_groups(self, parser_dict):
    """
    Resolves the include dict directive in the spec files.
    """
    for group, members in parser_dict.items():
        if group == 'include':
            if 'groups' in members:
                group_dict = members['groups']
                for group in group_dict.keys():
                    self._include_groups(group_dict)
        else:
            self._include_group(group, members)

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    for key, value in parser_dict.items():
        if isinstance(value, dict) and key.startswith('include:"'):
            group_name = key[9:]
            group_def = self._parse_dict(value)
            parser_dict[group_name] = group_def
            parser_dict.pop(key)
        elif isinstance(value, dict):
            self._include_groups(value)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSpecError('Unable to resolve non-Option type')
        # if there is a default set in the spec, add it to the defaults dict
        if arg.spec and arg.spec.default is not None:
            defaults[arg.name] = arg.spec.default
        # if there is a default set in the argspec, add it to the defaults dict
        if arg.argspec and arg.argspec.default is not None:
            defaults[arg.name] = arg.argspec.default
        # if there is a default set in the function itself, add it to the defaults dict
        if arg.function and arg.function.__defaults__ is not None:
            defaults[arg.name] = arg.function.__defaults__[0]
    return defaults

def get_spec_defaults(self):
    """
    Resolve arguments' values from spec and other sources.

    Returns:
        dict: A dictionary containing the resolved default values for the command.
    """

    defaults = {}
    for arg in self.args:
        # if there is a default set in the specification, use it
        if arg.default is not None:
            defaults[arg.name] = arg.default

        # if there is a default set in the spec options, use it
        if arg.options and arg.options[0].default is not None:
            defaults[arg.name] = arg.options[0].default

        # if there is a default set in the environment variables, use it
        env_var = arg.options[0].envar if arg.options[0].envar else arg.name
        env_default = os.environ.get(env_var, None)
        if env_default is not None:
            defaults[arg.name] = self.parse_value(env_default, arg.options[0].type, arg.options[0].choices)

        # if there is a default set in the file, use it
        if arg.options[0].alt is not None:
            defaults[arg.name] = self.parse_value(arg.options[0].alt, arg.options[0].type, arg.options[0].choices)

        # if there is a default set in the YAML file, use it
        if arg.options[0].stdin is not None:
            defaults[arg.name] = self.parse_value(arg.options[0].stdin, arg.options[0].type, arg.options[0].choices)

    return defaults

