    cli_args = {k: v for k, v in cli_args.items() if k in deprecated_args}
    answer_file_args = {k: v for k, v in answer_file_args.items() if k in deprecated_args}

    for arg_name, arg_new_name in deprecated_args.items():
        if arg_name in cli_args:
            value = cli_args[arg_name]
            print(f"WARNING: Argument {arg_name} has been deprecated in favor of {arg_new_name}. {arg_name} will be removed in a future version.")
            self.parsed_yaml[arg_new_name] = value
            del self.parsed_yaml[arg_name]

        if arg_name in answer_file_args:
            value = answer_file_args[arg_name]
            print(f"WARNING: Argument {arg_name} has been deprecated in favor of {arg_new_name}. {arg_name} will be removed in a future version.")
            self.parsed_yaml[arg_new_name] = value
            del self.parsed_yaml[arg_name]

    return self.parsed_yaml

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    option_specs = []
    for command in self.commands:
        if command.name == command_name:
            for option in command.options:
                option_specs.append(option.spec)
    return option_specs

def get_parser_option_specs(self, command_name):
    parser = argparse.ArgumentParser(prog=command_name)
    parser.add_argument('-h', '--help', action='store_true', help='Show this message and exit')
    commands_alias = {name: {'options': [], 'level': 0} for name in self.commands}
    for command in self.commands:
        name, aliases = command
        commands_alias[name]['level'] = commands_alias[name]['level'] + 1
        for alias in aliases:
            commands_alias[alias]['level'] = commands_alias[name]['level']
            commands_alias[alias]['options'] = commands_alias[name]['options']
    options = []
    for name, command in commands_alias.items():
        if command['level'] == 0:
            continue
        option = '_'.join(name.split())
        options.append(option)
    parser.add_argument('command', nargs='+')
    parser.add_argument('--opts', nargs='+', action='store', help='Options for the command')
    return parser.parse_args(self.arguments[0:1])

