def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars:
        for extra_var in extra_vars:
            if not isinstance(extra_var, dict):
                raise ValueError("Invalid extra-vars value")
            vars_dict.update(extra_var)

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars:
        for extra_var in extra_vars:
            if not isinstance(extra_var, dict):
                raise ValueError("extra_vars must be a list of dictionaries")
            vars_dict.update(extra_var)

def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend `vars_dict` with `extra_vars`

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict
    else:
        for extra_var in extra_vars:
            if not extra_var:
                continue
            for key, value in extra_var.items():
                if key in vars_dict:
                    if isinstance(value, dict) and isinstance(vars_dict[key], dict):
                        merge_extra_vars(vars_dict[key], value)
                    else:
                        vars_dict[key] = value
                else:
                    vars_dict[key] = value

def _convert_non_cli_args(self, parser_name, values_dict):
    arg_parsers = {
        "main": {
            "--max-memory": int,
            "--max-time": int,
            "--max-restarts": int
        },
        "virsh": {
            "--max-memory": int,
            "--max-time": int,
            "--max-restarts": int
        },
        "ospd": {
            "--max-memory": int,
            "--max-time": int,
            "--max-restarts": int
        },
    }

    if parser_name not in arg_parsers:
        raise ValueError(f"Unsupported parser name: {parser_name}")

    for arg, expected_type in arg_parsers[parser_name].items():
        value = values_dict.get(arg)
        if value is None:
            continue

        try:
            values_dict[arg] = expected_type(value)
        except ValueError:
            raise ValueError(f"{arg} must be of type {expected_type}, but given value is {value}")

    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if parser_name == "main":
        if "--verbose" in values_dict or "--quiet" in values_dict:
            values_dict["--verbosity"] = values_dict.pop("--verbose")
            values_dict["--verbosity"] = values_dict.pop("--quiet")

        if "--conf" in values_dict:
            values_dict["--conf"] = values_dict.pop("--conf")

        if "--version" in values_dict:
            values_dict["--version"] = values_dict.pop("--version")

    elif parser_name == "virsh":
        if "--connect" in values_dict:
            values_dict["--connect"] = values_dict.pop("--connect")

        if "--details" in values_dict:
            values_dict["--details"] = values_dict.pop("--details")

        if "--verbosity" in values_dict:
            values_dict["--verbosity"] = values_dict.pop("--verbosity")

        if "--version" in values_dict:
            values_dict["--version"] = values_dict.pop("--version")

    elif parser_name == "ospd":
        if "--listen-port" in values_dict:
            values_dict["--listen-port"] = values_dict.pop("--listen-port")

        if "--home-directory" in values_dict:
            values_dict["--home-directory"] = values_dict.pop("--home-directory")

        if "--config-file" in values_dict:
            values_dict["--config-file"] = values_dict.pop("--config-file")

        if "--log-file" in values_dict:
            values_dict["--log-file"] = values_dict.pop("--log-file")

        if "--version" in values_dict:
            values_dict["--version"] = values_dict.pop("--version")

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    try:
        parser = self.get_parser_instance(parser_name)
    except KeyError:
        raise KeyError("Parser not found")

    for _, arg in parser.values():
        if arg.type and _ in values_dict and values_dict[_]:
            values_dict[_] = arg.type(values_dict[_])

        if arg.multi_arg:
            for arg2 in values_dict[_]:
                if arg2.type:
                    arg2 = arg2.type(arg2)

    return values_dict

def _convert_non_cli_args(values_dict, parser_name):
    for option in parser.find_by_parser(parser_name):
        if option.name in values_dict:
            try:
                values_dict[option.name] = option.type(values_dict[option.name])
            except ValueError:
                values_dict[option.name] = option.default
    return values_dict

