def spec_extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to to the main entry point.

    :param subparser: the subparser object to extend.
    """

    spec_subparser = root_subparsers.add_parser('spec', help='Spec commands')

    for cmd in ('gen', 'parse'):
        subparser = spec_subparser.add_parser(cmd, help=f'{cmd} command')

        for arg in ('-t', '--target'):
            subparser.add_argument(arg, help='Target spec', metavar='SPEC')

        for arg in ('-h', '--build-file'):
            subparser.add_argument(arg, help='Build file', metavar='BUILD_FILE')

        for arg in ('-o', '--output'):
            subparser.add_argument(arg, help='Output file', metavar='OUTPUT_FILE')

        subparser.set_defaults(func=getattr(self, f'{cmd}_spec'))

    for cmd in ('gen', 'parse'):
        subparser = spec_subparser.add_parser(cmd, help=f'{cmd} command')

        for arg in ('-s', '--scope'):
            subparser.add_argument(arg, help='Scope', metavar='SCOPE')

    for cmd in ('gen', 'parse'):
        subparser = spec_subparser.add_parser(cmd, help=f'{cmd} command')
        subparser.set_defaults(func=getattr(self, f'{cmd}_spec'))

